// WA-3 (2026-09-25): what the Cloud API receives, one item per call, in order.
// The payload shapes are the ones in src/channel/whatsapp.ts; tests/n8n-whatsapp-send.test.ts
// runs THIS code and compares its output with them.
//
// Input, from the Turno: { to, markRead: wamid } as soon as her message arrives, then
//                        { to, bubbles: [{ text, delayMs }] } with the reply
//        from the Relogio: { to, via: "text", body } or { to, via: "template", name, language, variables }
//                          or { to, via: "buttons", body, buttons: [{ id, title }] } (up to 3, inside the window)
//
// CANAL_ATIVO stays false until the number is registered and the partner's values are in:
// while false, nothing leaves, whatever calls this.
const CANAL_ATIVO = true;
const PHONE_NUMBER_ID = '1370670962794717';
const API = 'https://graph.facebook.com/v21.0/';

const out = [];
if (!CANAL_ATIVO || !/^[0-9]+$/.test(PHONE_NUMBER_ID)) return out;
const url = API + PHONE_NUMBER_ID + '/messages';
const text = (to, body) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body } });
const template = (to, name, language, variables) => ({
  messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'template',
  template: { name, language: { code: language }, ...(variables.length ? { components: [{ type: 'body', parameters: variables.map((t) => ({ type: 'text', text: t })) }] } : {}) },
});
const buttons = (to, body, list) => ({
  messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'interactive',
  interactive: { type: 'button', body: { text: body }, action: { buttons: list.map((b) => ({ type: 'reply', reply: { id: String(b.id), title: String(b.title) } })) } },
});
const read = (messageId) => ({ messaging_product: 'whatsapp', status: 'read', message_id: messageId, typing_indicator: { type: 'text' } });
// Typing pauses come from the turn (pacing); capped so one bubble never holds the line.
const pause = (ms) => Math.min(25, Math.max(0, Math.round(Number(ms ?? 0) / 1000)));

for (const item of $input.all()) {
  const j = item.json ?? {};
  const to = String(j.to ?? '').replace(/[^0-9]/g, '');
  if (!to) continue;
  if (typeof j.markRead === 'string' && j.markRead) {
    out.push({ json: { url, to, delaySec: 0, payload: read(j.markRead) } });
  } else if (Array.isArray(j.bubbles) && j.bubbles.length) {
    for (const b of j.bubbles) {
      const body = String(b?.text ?? '').trim();
      if (body) out.push({ json: { url, to, delaySec: pause(b.delayMs), payload: text(to, body) } });
    }
  } else if (j.via === 'template' && j.name) {
    out.push({ json: { url, to, delaySec: 0, payload: template(to, String(j.name), String(j.language ?? 'pt_BR'), (j.variables ?? []).map(String)) } });
  } else if (j.via === 'buttons') {
    // Before the plain-text branch: a question whose buttons fell off would ask her to tap
    // buttons that do not exist. Out of Meta's limits, nothing is sent.
    const list = Array.isArray(j.buttons) ? j.buttons : [];
    const body = String(j.body ?? '').trim();
    if (body && list.length >= 1 && list.length <= 3 && list.every((b) => b && b.id && b.title)) {
      out.push({ json: { url, to, delaySec: 0, payload: buttons(to, body, list) } });
    }
  } else if (typeof j.body === 'string' && j.body.trim()) {
    out.push({ json: { url, to, delaySec: 0, payload: text(to, j.body.trim()) } });
  }
}
return out;

